-- KOMBAX RC13 build 20071 · 124
-- Normas Social 1.4 alineadas con control adulto, denuncia de mensajes y
-- estándares de seguridad infantil exigibles a una aplicación Social.
begin;

update public.textos_legales
set vigente=false
where tipo='comunidad_general' and vigente and version<>'1.4.0';

insert into public.textos_legales(club_id,tipo,version,cuerpo,vigente)
select c.id,'comunidad_general','1.4.0',
E'NORMAS DE KOMBAX SOCIAL · 1.4\n\nKOMBAX Social es una capa pública general y opcional, separada de la Comunidad del Club y de la gestión administrativa. Activarla no publica email, teléfono, fecha de nacimiento, domicilio, documentos, finanzas ni relaciones familiares.\n\nIdentidad y afiliación. Un perfil Miembro puede mostrar su afiliación a un club cuando KOMBAX la verifica contra una membresía real y activa. La afiliación puede ocultarse públicamente sin alterar la pertenencia administrativa al club. El perfil del Miembro y el perfil del Club siguen siendo identidades independientes.\n\nContenido. Se permiten actualizaciones deportivas, resultados, eventos, oportunidades y publicaciones de afiliación verificadas. Se prohíben acoso, amenazas, odio o discriminación, violencia ilícita, datos privados de terceros, suplantación, spam, contenido ilegal y cualquier contenido o conducta que explote, abuse sexualmente, sexualice, capte, extorsione, trafique o ponga en peligro a una persona menor de edad. KOMBAX mantiene tolerancia cero frente a la explotación y el abuso sexual infantil (EASI/CSAE) y al material de abuso sexual infantil (CSAM).\n\nContacto KOMBAX. Para iniciar una conversación es obligatorio enviar una solicitud con motivo y primer mensaje. El chat solo se habilita cuando la otra identidad acepta. Una vez aceptado, el historial permanece abierto y no tiene un límite artificial de mensajes. En esta fase el chat es solo de texto: no admite imágenes, vídeos, audios, archivos ni grupos. Cualquiera de los participantes puede cerrar su conversación.\n\nMenores. Una persona menor de 18 años puede utilizar las funciones privadas de Mi club que le correspondan, pero para activar una identidad pública en KOMBAX Social necesita la autorización de un padre, madre o tutor responsable vinculado y autenticado. Antes de activar Social debe revisar un recordatorio específico de seguridad. La autorización adulta puede revocarse y, si se revoca, el perfil Social del menor se oculta y se bloquean nuevas publicaciones hasta una nueva autorización y reactivación. El Contacto KOMBAX entre perfiles personales permanece bloqueado para menores de 18 años.\n\nSeguridad, bloqueo y denuncia. Los usuarios pueden bloquear perfiles y denunciar publicaciones, comentarios, perfiles y mensajes concretos. Al denunciar un mensaje privado, Moderación recibe únicamente la evidencia vinculada al mensaje denunciado y el contexto aportado por la persona denunciante; no obtiene acceso general a la conversación. Un bloqueo impide iniciar o continuar Contacto KOMBAX.\n\nProtección infantil. Está prohibido crear, solicitar, almacenar, compartir, promocionar o facilitar CSAM o cualquier forma de EASI/CSAE. Las denuncias relacionadas con riesgo sexual de menores reciben prioridad. Cuando KOMBAX obtenga conocimiento real de contenido de esta naturaleza deberá retirarlo o bloquearlo, preservar la trazabilidad estrictamente necesaria y activar el procedimiento de escalado y comunicación a las autoridades competentes conforme a la legislación aplicable.\n\nModeración. KOMBAX puede ocultar contenido público o mensajes denunciados, revisar denuncias, advertir, escalar casos y suspender el acceso social sin alterar la membresía administrativa del club. El rol Moderador está separado del Owner/Administración y no tiene acceso general a Finanzas, documentos privados, gestión de cuentas o solicitudes de eliminación.',true
from public.clubes c
on conflict(club_id,tipo,version) do update set cuerpo=excluded.cuerpo,vigente=true;

notify pgrst,'reload schema';
commit;
